// Define the specific variables you want to check and convert
const targetFields = [
  "likelihood",
  "severity",
  "velocity",
  "persistence",
  "preparedness",
  "risk_score"
];

// Loop over all incoming items
for (const item of $input.all()) {

  // Check each target field for the current item
  for (const field of targetFields) {

    // Ensure the field actually exists in the JSON output
    if (item.json[field] !== undefined) {
      let value = item.json[field];

      // Check if the value is a number AND if it is a float (has a remainder when divided by 1)
      if (typeof value === 'number' && value % 1 !== 0) {

        // Convert the float to an integer. 
        // Using Math.round() rounds to the nearest whole number (e.g., 2.5 becomes 3).
        // If you prefer to simply drop the decimal (2.9 becomes 2), change Math.round to Math.floor
        item.json[field] = Math.round(value);
      }
    }
  }
}

// Return the modified items
return $input.all();

// Define the property name where your text input lives. 
// Change 'text' to match your previous node's output (e.g., 'data', 'response', 'content').
const inputProperty = 'text';

const newItems = [];

for (const item of $input.all()) {
  try {
    let rawText = item.json.output[0].content[0].text;

    // 1. Strip out markdown formatting if present (```json ... ```)
    if (typeof rawText === 'string') {
        rawText = rawText.replace(/```json/gi, '')
                         .replace(/```/g, '')
                         .trim();
    }

    // 2. Parse the string into a JavaScript object/array
    const parsedData = JSON.parse(rawText);

    // 3. Map to n8n's expected format ({ json: { ... } })
    // If it's an array, split it into multiple items.
    if (Array.isArray(parsedData)) {
      for (const element of parsedData) {
        newItems.push({ json: element });
      }
    } else {
      // If it's a single object, return it as one item.
      newItems.push({ json: parsedData });
    }
  } catch (error) {
    // If parsing fails, output the error to help with debugging
    newItems.push({
      json: {
        error: "Failed to parse JSON",
        details: error.message,
        originalData: item.json[inputProperty]
      }
    });
  }
}

return newItems;

// Loop over all incoming items
for (const item of $input.all()) {
  // Check if the 'topic' field exists in the item's JSON data
  if (item.json.topic) {
    let topic = item.json.topic;

    // 1. Replace underscores and dashes with spaces 
    // (Change ' ' to '' if you want to delete them entirely without adding a space)
    let cleanTopic = topic.replace(/[-_]/g, ' ');

    // 2. Capitalize the first letter of the resulting string
    let formattedTopic = cleanTopic.charAt(0).toUpperCase() + cleanTopic.slice(1);

    // 3. Overwrite the original 'topic' field with the formatted string
    // (Alternatively, use item.json.formattedTopic = formattedTopic to keep the original)
    item.json.topic = formattedTopic;
  }
}

// Return the modified items
return $input.all();

