// Get all incoming items
const items = $input.all();

// Map through the items and format each topic
const formattedTopics = items.map(item => {
  const rawTopic = item.json.topic;

  // Clean up the string: replace underscores with spaces and Title Case it
  // e.g., "supply_chain" -> "Supply Chain", "ai_gov" -> "Ai Gov"
  const cleanTopic = rawTopic
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');

  // Wrap in bullet and bold formatting
  return `• *${cleanTopic}*`;
}).join('\\n');

// Return a single item containing the formatted string
return [
  {
    json: {
      slack_formatted_topics: formattedTopics
    }
  }
];

